const database = NEOFIND_DATABASE;
const neoDatabase = NEOFIND_DATABASE;
const databaseByLanguage = {
  pl: NEOFIND_DATABASE.map(r => ({...r, ...r.pl, language:"pl"})),
  en: NEOFIND_DATABASE.map(r => ({...r, ...r.en, language:"en"})),
  es: NEOFIND_DATABASE.map(r => ({...r, ...r.es, language:"es"})),
  fr: NEOFIND_DATABASE.map(r => ({...r, ...r.fr, language:"fr"}))
};

function searchNeoFindDatabase(query, language = "pl") {
  const q = String(query ?? "").trim().toLowerCase();
  if (!q) return [];
  const source = databaseByLanguage[language] || databaseByLanguage.pl;
  return source.filter(r =>
    String(r.name || "").toLowerCase().includes(q) ||
    String(r.description || "").toLowerCase().includes(q) ||
    String((r.aliases || []).join(" ")).toLowerCase().includes(q) ||
    String(r.searchable || "").includes(q)
  );
}

if (typeof window !== "undefined") {
  window.NEOFIND_DATABASE = NEOFIND_DATABASE;
  window.neoDatabase = neoDatabase;
  window.database = database;
  window.databaseByLanguage = databaseByLanguage;
  window.searchNeoFindDatabase = searchNeoFindDatabase;
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    NEOFIND_DATABASE,
    database,
    neoDatabase,
    databaseByLanguage,
    searchNeoFindDatabase
  };
}
